"""**2-OPT**

Generarea unui vecin cu 2 edge optimization.
"""

def two_opt(sol, dimension):
  x = sol[:]
  i=random.randint(0, dimension-1)
  j=random.randint(0, dimension-1)
  while i==j:
    j=random.randint(0, dimension-1)
  if i>j:
    i, j = j, i

  x[i:j] = reversed(x[i:j])

  return x

"""Funcția pentru implementarea Tabu Search

"""

def tabu_search_TSP(dm, dimension, max_iterations, tabu_size, method):
  """
  Implementeaza algoritmul Tabu Search pentru problema TSP, folosind doua
  metode diferite de generare a vecinilor.
  Pasi importanti:
  -generez o solutie pentru TSP
  -initializez lista tabu care va fi memoria: ne arata daca o solutie a fost
  explorata si cat timp nu mai trebuie sa o exploram
  -pentru fiecare iteratie se genereaza vecini aleatori (2-swap sau 2-opt)
  -se selecteaza cel mai bun vecin care nu se afla in lista tabu (nu a fost explorat)
  -se actualizeaza solutia curenta, apoi cea optima
  -spre finalul iteratiei se actualizeaza lista tabu
  -se va returna cea mai buna solutie gasita
  -----
  INPUT
  dm: matricea distantelor intre orase
  dimension: dimensiunea matricii distantelor
  max_iterations: numarul maxim de iteratii dupa care se opreste algoritmul (stop criterion)
  tabu_size: dimensiunea listei tabu
  method: ce metoda de generare a vecinilor folosim
  -----
  OUTPUT:
  best: cea mai buna solutie
  best_fitness: fitness-ul celei mai bune solutii
  memory: memoria intre iteratii care va fi folosita la grafic pentru a analiza
  comportamentul algoritmului pe parcursul rularii
  """

  current = generate_solution_TSP(dimension)
  best = current[:]

  tabu_list = []
  memory = []
  best_fitness = fitness_TSP(best, dm)

  for _ in range(max_iterations):

    best_neighbor = None
    best_neighbor_fitness = float('inf')

    for _ in range(50):

      if method == "2-swap":
        neighbor = two_swap(current, dimension)
      else:
        neighbor = two_opt(current, dimension)

      if neighbor in tabu_list:
        continue

      neighbor_fitness = fitness_TSP(neighbor, dm)

      if neighbor_fitness < best_neighbor_fitness:
        best_neighbor = neighbor
        best_neighbor_fitness = neighbor_fitness

    if best_neighbor is None:
      continue

    current = best_neighbor

    if best_neighbor_fitness < best_fitness:
      best = best_neighbor[:]
      best_fitness = best_neighbor_fitness

    memory.append(best_fitness)

    tabu_list.append(best_neighbor)

    if len(tabu_list) > tabu_size:
      tabu_list.pop(0)

  return best, best_fitness, memory

"""Functia care permite rularea algoritmului Tabu Search pentru TSP de mai multe ori."""

def ts_TSP_n_times(n, max_iterations, tabu_size, dm, dimension, method):
  """
  Functie care permite rularea de mai multe ori a algoritmului Tabu Search pentru
  problema TSP.
  -----
  INPUT:
  n: numarul de rulari efectuate
  max_iterations: numarul maxim de iteratii dupa care se opreste algoritmul (stop criterion)
  tabu_size: dimensiunea listei tabu
  dm: matricea distantelor intre orase
  dimension: dimensiunea matricii distantelor
  method: ce metoda de generare a vecinilor folosim
  -----
  OUTPUT:
  best_sol: lista celor mai bune solutii din cele n rulari
  average_time: lista cu timpul estimativ al fiecarei rulari
  memory_list: lista cu memoria intre iteratii pentru a observa comportamentul
  algoritmului pe parcursul rularii
  """
  best_sol = []
  average_time = 0
  memory_list =[]

  for _ in range(n):
    start = time.time()

    best_results, best_fitness, memory = tabu_search_TSP(dm, dimension, max_iterations, tabu_size, method)
    stop = time.time() - start
    average_time += stop

    memory_list.append(memory)
    best_sol.append((best_results, best_fitness))

  average_time /= n

  return best_sol, average_time, memory_list

