"""Functia care implementeaza Tabu Search pentru problema rucsacului"""

def tabu_search_rucsac(objects, max_capacity, max_iterations, tabu_size):
  """
  Functia implementeaza algoritmul Tabu Search pentru rezolvarea problemei
  rucsacului. Acesta urmareste urmatorii pasi:
  -generarea unei solutii initiale
  -initializarea listei tabu
  -pentru fiecare iteratie se exploreaza vecinii
  -este ales vecinul cel mai bun
  -solutia curenta este actualizata, iar apoi cea mai buna solutie
  -----
  INPUT:
  objects: datele evaluate
  max_capacity: greutatea maxima admisa in rucsac
  max_iterations: numar de iteratii pentru care se repeta algoritmul (stop critirion)
  tabu_size: dimensiunea listei tabu
  -----
  OUTPUT:
  best: cea mai buna solutie
  best_fitness: fitness-ul celei mai bune solutii
  memory: memoria intre iteratii care va fi folosita la grafic pentru a analiza
  comportamentul algoritmului pe parcursul rularii
  """
  n = len(objects)
  current = generate_valid_solution_rucsac(n, objects, max_capacity)
  best = current[:]
  tabu_list = []
  memory = []
  best_fitness = fitness_rucsac(objects, best, max_capacity)

  for _ in range(max_iterations):
    best_n = None
    best_n_fitness = -1
    for _ in range(50):
      neighbor = random_neighbor_rucsac(current)
      if neighbor in tabu_list:
        continue
      neighbor_fitness = fitness_rucsac(objects, neighbor, max_capacity)

      if neighbor_fitness > best_n_fitness:
        best_n = neighbor
        best_n_fitness = neighbor_fitness

    if best_n is None:
      continue

    current = best_n
    if best_n_fitness > best_fitness:
      best = best_n
      best_fitness = best_n_fitness

    memory.append(best_fitness)
    tabu_list.append(best_n)
    if len(tabu_list) > tabu_size:
      tabu_list.pop(0)

  return best, best_fitness, memory

"""Functia care permite rularea de mai multe ori a algoritmului Tabu Search."""

def ts_rucsac_n_times(n, max_iterations, tabu_size, objects, max_capacity):
  """
  Functie care permite rularea de mai multe ori a algoritmului Tabu Search pentru
  problema rucsacului.
  -----
  INPUT:
  n: numarul de rulari efectuate
  max_iterations: numarul maxim de iteratii dupa care se opreste algoritmul (stop criterion)
  tabu_size: dimensiunea listei tabu
  objects: datele evaluate
  max_capacity: greutatea maxima admisa in rucsac
  -----
  OUTPUT:
  best_sol: lista celor mai bune solutii din cele n rulari
  average_time: lista cu timpul estimativ al fiecarei rulari
  memory_list: lista cu memoria intre iteratii pentru a observa comportamentul
  algoritmului pe parcursul rularii
  """
  best_sol = []
  average_time = 0
  memory_list = []

  for _ in range(n):
    start = time.time()

    best_results, best_fitness, memory = tabu_search_rucsac(objects, max_capacity, max_iterations, tabu_size)
    stop = time.time() - start
    average_time += stop

    memory_list.append(memory)
    best_sol.append((best_results, best_fitness))

  average_time /= n

  return best_sol, average_time, memory_list

